    /** Material icon name for a place category (OSM value). */
    fun forCategory(cat: String): String = when (cat) {
        "supermarket", "convenience", "grocery", "greengrocer", "butcher", "bakery", "deli" -> "cart"
        "cafe", "coffee", "ice_cream" -> "cafe"
        "restaurant", "food_court", "fast_food" -> "restaurant"
        "pub", "bar", "biergarten", "nightclub" -> "bar"
        "fuel", "charging_station" -> "charging"
        "bicycle", "bicycle_parking", "bicycle_rental", "bicycle_repair_station" -> "bike"
        "car_repair", "hardware", "doityourself" -> "wrench"
        "school", "university", "college", "kindergarten", "library" -> "school"
        "hospital", "clinic", "doctors", "dentist" -> "hospital"
        "pharmacy", "chemist" -> "pharmacy"
        "bank", "atm", "bureau_de_change" -> "bank"
        "park", "garden", "nature_reserve", "playground", "wood", "forest" -> "park"
        "station", "bus_stop", "halt", "tram_stop", "subway_entrance" -> "train"
        "city", "town", "village", "suburb", "hamlet", "neighbourhood", "quarter" -> "city"
        "house", "residential", "street", "road", "tertiary", "secondary", "primary", "unclassified", "living_street" -> "home"
        "parking" -> "parking"
        "hotel", "guest_house", "hostel" -> "hotel"
        "clothes", "shoes", "department_store", "mall", "gift", "jewelry", "mobile_phone", "electronics" -> "bag"
        else -> "place"
    }
}

/** Minimal SVG path-data parser (M L H V C S Q T Z, absolute and relative) → drawing commands. */
object SvgPath {
    interface Sink {
        fun moveTo(x: Float, y: Float); fun lineTo(x: Float, y: Float)
        fun cubicTo(x1: Float, y1: Float, x2: Float, y2: Float, x: Float, y: Float); fun close()
    }

    fun parse(d: String, out: Sink) {
        val toks = Regex("[MmLlHhVvCcSsQqTtZz]|-?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?").findAll(d).map { it.value }.toList()
        var i = 0
        var cx = 0f; var cy = 0f; var sx = 0f; var sy = 0f
        var lastC2x = 0f; var lastC2y = 0f; var lastQx = 0f; var lastQy = 0f
        var cmd = ' '; var prev = ' '
        fun num(): Float = toks[i++].toFloat()
        fun isNum() = i < toks.size && !toks[i][0].isLetter()
        while (i < toks.size) {
            if (!isNum()) { cmd = toks[i++][0] }
            val rel = cmd.isLowerCase()
            when (cmd.uppercaseChar()) {
                'M' -> { var x = num(); var y = num(); if (rel) { x += cx; y += cy }
                    out.moveTo(x, y); cx = x; cy = y; sx = x; sy = y
                    cmd = if (rel) 'l' else 'L' }        // following pairs are line-tos
                'L' -> { var x = num(); var y = num(); if (rel) { x += cx; y += cy }; out.lineTo(x, y); cx = x; cy = y }
                'H' -> { var x = num(); if (rel) x += cx; out.lineTo(x, cy); cx = x }
                'V' -> { var y = num(); if (rel) y += cy; out.lineTo(cx, y); cy = y }
                'C' -> { var x1 = num(); var y1 = num(); var x2 = num(); var y2 = num(); var x = num(); var y = num()
                    if (rel) { x1 += cx; y1 += cy; x2 += cx; y2 += cy; x += cx; y += cy }
                    out.cubicTo(x1, y1, x2, y2, x, y); lastC2x = x2; lastC2y = y2; cx = x; cy = y }
                'S' -> { val pu = prev.uppercaseChar()
                    val x1 = if (pu == 'C' || pu == 'S') 2 * cx - lastC2x else cx
                    val y1 = if (pu == 'C' || pu == 'S') 2 * cy - lastC2y else cy
                    var x2 = num(); var y2 = num(); var x = num(); var y = num()
                    if (rel) { x2 += cx; y2 += cy; x += cx; y += cy }
                    out.cubicTo(x1, y1, x2, y2, x, y); lastC2x = x2; lastC2y = y2; cx = x; cy = y }
                'Q' -> { var qx = num(); var qy = num(); var x = num(); var y = num()
                    if (rel) { qx += cx; qy += cy; x += cx; y += cy }
                    out.cubicTo(cx + 2f / 3 * (qx - cx), cy + 2f / 3 * (qy - cy), x + 2f / 3 * (qx - x), y + 2f / 3 * (qy - y), x, y)
                    lastQx = qx; lastQy = qy; cx = x; cy = y }
                'T' -> { val pu = prev.uppercaseChar()
                    val qx = if (pu == 'Q' || pu == 'T') 2 * cx - lastQx else cx
                    val qy = if (pu == 'Q' || pu == 'T') 2 * cy - lastQy else cy
                    var x = num(); var y = num(); if (rel) { x += cx; y += cy }
                    out.cubicTo(cx + 2f / 3 * (qx - cx), cy + 2f / 3 * (qy - cy), x + 2f / 3 * (qx - x), y + 2f / 3 * (qy - y), x, y)
                    lastQx = qx; lastQy = qy; cx = x; cy = y }
                'Z' -> { out.close(); cx = sx; cy = sy }
                else -> throw IllegalArgumentException("unsupported path command $cmd")
            }
            prev = cmd
        }
    }
}
